// velocity-marquee. Generated by scripts/build-esm.mjs from the DEFAULTS of the engine.

export interface VelocityMarqueeSettings {
  /** px/s. Speed of the ribbon when the page stands still. Default: 46. */
  cruise?: number;
  /** left or right. Way the ribbon runs at rest. Default: 'left'. */
  direction?: string;
  /** factor. Share of the scroll speed added to the ribbon. Default: 1.5. */
  boost?: number;
  /** px/s. Fastest the ribbon may ever run. Default: 2400. */
  maxSpeed?: number;
  /** 0 to 1. How fast the ribbon answers the scroll. Default: 0.12. */
  ease?: number;
  /** deg. Largest lean, reached at top speed. Default: 7. */
  skew?: number;
  /** true or false. Scrolling up runs the ribbon backwards. Default: true. */
  reverse?: boolean;
  /** px/s. Speed under reduced motion (0 stands still). Default: 0. */
  reducedSpeed?: number;
  /** true or false. Writes the live state in attributes. Default: false. */
  debug?: boolean;
}

export interface Instance {
  destroy(): void;
  [key: string]: unknown;
}

export interface Library {
  mount(element: Element, settings?: VelocityMarqueeSettings): Instance | null;
  destroy(element: Element): void;
  auto(root?: ParentNode): void;
  defaults: Required<VelocityMarqueeSettings> | null;
  [key: string]: unknown;
}

/** Runs the engine once and returns window.VelocityMarquee, or null on a server. */
export function load(): Library | null;
/** Mounts the effect on one element. Does nothing, and returns null, on a server. */
export function mount(element: Element | null, settings?: VelocityMarqueeSettings): Instance | null;
export function destroy(element: Element | null): void;
/** Mounts every marked element inside root, the document by default. */
export function auto(root?: ParentNode): void;
